(function() {
  const dropZone = document.getElementById('dropZone');
  const fileInput = document.getElementById('fileInput');
  const langSel = document.getElementById('langSel');
  const startBtn = document.getElementById('startBtn');
  const fileList = document.getElementById('fileList');
  const progressCard = document.getElementById('progressCard');
  const progressBar = document.getElementById('progressBar');
  const progressLabel = document.getElementById('progressLabel');
  const progressPct = document.getElementById('progressPct');
  const status = document.getElementById('status');
  const output = document.getElementById('output');
  const summary = document.getElementById('summary');
  const copyBtn = document.getElementById('copyOutput');
  const downloadBtn = document.getElementById('downloadBtn');
  const clearBtn = document.getElementById('clearBtn');

  let selectedFiles = [];

  function fmtSize(bytes) {
    if (bytes < 1024) return bytes + ' B';
    if (bytes < 1048576) return (bytes / 1024).toFixed(1) + ' KB';
    return (bytes / 1048576).toFixed(2) + ' MB';
  }

  function renderFileList() {
    if (!selectedFiles.length) {
      fileList.innerHTML = '';
      return;
    }
    fileList.innerHTML = selectedFiles.map((f, i) =>
      '<div data-idx="' + i + '" style="display:flex;align-items:center;gap:.6rem;padding:.5rem .7rem;background:var(--bg-secondary);border-radius:8px;border:1px solid var(--border);">' +
        '<div style="width:38px;height:38px;border-radius:6px;background:linear-gradient(135deg,var(--primary),#7dd3fc);display:flex;align-items:center;justify-content:center;color:#fff;font-size:.95rem;flex-shrink:0;">' + (f.type.indexOf('png') > -1 ? '🖼️' : '🖼️') + '</div>' +
        '<div style="flex:1;min-width:0;">' +
          '<div style="font-size:.88rem;font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + escapeHtml(f.name) + '</div>' +
          '<div style="font-size:.72rem;opacity:.6;">' + fmtSize(f.size) + '</div>' +
        '</div>' +
        '<button class="copy-btn" data-rm="' + i + '" style="background:var(--bg-secondary);color:var(--text);font-size:.7rem;padding:.25rem .55rem;">移除</button>' +
      '</div>'
    ).join('');
    fileList.querySelectorAll('[data-rm]').forEach(btn => {
      btn.onclick = function(e) {
        e.stopPropagation();
        const idx = parseInt(btn.getAttribute('data-rm'));
        selectedFiles.splice(idx, 1);
        renderFileList();
      };
    });
  }

  function escapeHtml(s) {
    return String(s).replace(/[&<>"']/g, function(c) {
      return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c];
    });
  }

  function addFiles(files) {
    const arr = Array.from(files).filter(f => f.type.indexOf('image/') === 0);
    if (!arr.length) {
      showToast('请选择图片文件', '⚠️');
      return;
    }
    selectedFiles = selectedFiles.concat(arr);
    renderFileList();
  }

  dropZone.onclick = function() { fileInput.click(); };
  dropZone.ondragover = function(e) { e.preventDefault(); dropZone.style.borderColor = 'var(--primary)'; dropZone.style.background = 'rgba(125,211,252,.1)'; };
  dropZone.ondragleave = function(e) { e.preventDefault(); dropZone.style.borderColor = 'var(--border)'; dropZone.style.background = 'var(--bg-secondary)'; };
  dropZone.ondrop = function(e) {
    e.preventDefault();
    dropZone.style.borderColor = 'var(--border)';
    dropZone.style.background = 'var(--bg-secondary)';
    if (e.dataTransfer && e.dataTransfer.files) addFiles(e.dataTransfer.files);
  };
  fileInput.onchange = function(e) {
    if (e.target.files) addFiles(e.target.files);
    fileInput.value = '';
  };

  function setProgress(pct, label, sub) {
    progressCard.style.display = 'block';
    progressBar.style.width = pct + '%';
    progressPct.textContent = Math.round(pct) + '%';
    if (label) progressLabel.textContent = label;
    if (sub) status.textContent = sub;
  }

  function loadScript(src) {
    return new Promise(function(resolve, reject) {
      if (window.Tesseract) return resolve();
      const s = document.createElement('script');
      s.src = src;
      s.onload = function() { resolve(); };
      s.onerror = function() { reject(new Error('无法加载 Tesseract.js CDN')); };
      document.head.appendChild(s);
    });
  }

  async function run() {
    if (!selectedFiles.length) {
      showToast('请先选择图片', '⚠️');
      return;
    }
    if (typeof Tesseract === 'undefined') {
      setProgress(5, '加载 OCR 引擎...', '首次加载约需几秒，请稍候');
      try {
        await loadScript('https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js');
      } catch (err) {
        showToast('OCR 引擎加载失败：' + err.message, '❌');
        status.textContent = '加载失败，请检查网络后重试';
        return;
      }
    }

    startBtn.disabled = true;
    startBtn.textContent = '识别中...';
    startBtn.style.opacity = '0.6';
    output.value = '';
    summary.textContent = '';

    const lang = langSel.value || 'chi_sim+eng';
    const total = selectedFiles.length;
    const results = [];
    const t0 = Date.now();

    try {
      for (let i = 0; i < total; i++) {
        const file = selectedFiles[i];
        const fileStart = Date.now();
        setProgress(
          (i / total) * 100,
          '识别 ' + (i + 1) + ' / ' + total + '：' + file.name,
          '准备识别...'
        );

        const r = await Tesseract.recognize(file, lang, {
          logger: function(m) {
            if (m && typeof m.progress === 'number') {
              const filePct = m.progress;
              const overall = ((i + filePct) / total) * 100;
              const phaseMap = {
                'loading tesseract core': '加载 OCR 内核',
                'initializing tesseract': '初始化引擎',
                'loading language traineddata': '下载语言模型',
                'initializing api': '初始化 API',
                'recognizing text': '识别文字'
              };
              const phaseName = phaseMap[m.status] || (m.status || '');
              setProgress(overall, '识别 ' + (i + 1) + ' / ' + total + '：' + file.name, phaseName + ' ' + Math.round(filePct * 100) + '%');
            }
          }
        });

        const text = (r && r.data && r.data.text) ? r.data.text.trim() : '';
        const elapsed = ((Date.now() - fileStart) / 1000).toFixed(1);
        results.push({ name: file.name, text: text, elapsed: elapsed, confidence: (r && r.data && r.data.confidence) ? Math.round(r.data.confidence) : null });
      }

      const finalText = results.map(function(r) {
        return '=== ' + r.name + ' ===\n\n' + (r.text || '（未识别到文字）');
      }).join('\n\n');

      output.value = finalText;
      const totalElapsed = ((Date.now() - t0) / 1000).toFixed(1);
      const confList = results.map(function(r) { return r.confidence; }).filter(function(c) { return c !== null; });
      const avgConf = confList.length ? Math.round(confList.reduce(function(a,b){return a+b;}, 0) / confList.length) : null;
      summary.textContent = '✅ 完成 ' + total + ' 张图片，总耗时 ' + totalElapsed + ' 秒' +
        (avgConf !== null ? '，平均置信度 ' + avgConf + '%' : '');

      setProgress(100, '✅ 识别完成', '共处理 ' + total + ' 张图片，耗时 ' + totalElapsed + ' 秒');
      showToast('识别完成！', '✅');
    } catch (err) {
      console.error(err);
      status.textContent = '识别出错：' + (err && err.message ? err.message : err);
      showToast('识别失败：' + err.message, '❌');
    } finally {
      startBtn.disabled = false;
      startBtn.textContent = '🚀 开始识别';
      startBtn.style.opacity = '1';
    }
  }

  startBtn.onclick = run;

  copyBtn.onclick = function() {
    if (!output.value.trim()) { showToast('暂无内容可复制', '⚠️'); return; }
    copyToClipboard(output.value);
  };

  downloadBtn.onclick = function() {
    if (!output.value.trim()) { showToast('暂无内容可下载', '⚠️'); return; }
    const blob = new Blob([output.value], { type: 'text/plain;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    const stamp = new Date().toISOString().slice(0, 19).replace(/[:T]/g, '-');
    a.href = url;
    a.download = 'OCR-识别结果-' + stamp + '.txt';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    showToast('已下载 TXT 文件', '✅');
  };

  clearBtn.onclick = function() {
    output.value = '';
    summary.textContent = '';
    selectedFiles = [];
    renderFileList();
    progressCard.style.display = 'none';
    progressBar.style.width = '0%';
    showToast('已清空', '🧹');
  };

  // 初始状态
  summary.textContent = '提示：请上传图片后点击"开始识别"';
})();
